#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    int volume = 0;
    int now = 0; //直前の水の追加の時刻 (最初は0とする)
    for (int i = 0; i < n; ++i) {
        int t, v;
        cin >> t >> v;
        volume -= (t - now); //前の水の追加からの経過時間
        volume = max(volume, 0);
        volume += v; //水の追加
        now = t;
    }
    cout << volume << endl;
}
